from pathlib import Path
import json
P=Path('PCB');baseline=json.loads((P/'manifests/routing-optimized-source-v13.json').read_text());plan=json.loads((P/'manifests/hy20-local-routing-v13.json').read_text());check=json.loads((P/'manifests/hy20-local-routing-check-v13.json').read_text())
assert not check['conflicts'] and not check['viasNearConnectorPads']
cs=json.loads((P/'manifests/pads-after-routing-opt-v13.json').read_text(encoding='utf8'))['result'];rows=[{'ref':c['ref'],'uid':c['uid'],'x':c['x'],'y':5/.0254,'nets':{p['number']:p['net'] for p in c['pads']}} for c in cs if c['ref'] in ['J1','J2','J3']]
guard=(P/'scripts/read-pcb-source-v13.js').read_text().split('return {source:')[0]
code=guard+'const rows='+json.dumps(rows)+";const EPCB_LayerId={TOP:1};const all=await eda.pcb_PrimitiveComponent.getAll();const old=all.filter(c=>['J1','J2','J3'].includes(c.getState_Designator()));const staged=await eda.pcb_PrimitiveComponent.get('04c7d9b12d6863a6');if(old.length!==3||!staged||all.length!==105)throw Error('Unexpected component state');if(old.some(c=>c.getState_SupplierId()!=='C265102'))throw Error('Unexpected old connector');await eda.pcb_PrimitiveComponent.delete(old.map(c=>c.getState_PrimitiveId()));const out=[];for(const z of rows){let c=z.ref==='J1'?staged:await eda.pcb_PrimitiveComponent.create({uuid:'9068c861be90912a',libraryUuid:'52c709566e222603927d1a7d15a5e220a7f38cb78f29ecab14bf35ab4cfcb0b9'},EPCB_LayerId.TOP,z.x,z.y,0,false);if(!c)throw Error('Create '+z.ref);c=await eda.pcb_PrimitiveComponent.modify(c,{x:z.x,y:z.y,rotation:0,designator:z.ref,uniqueId:z.uid,name:'ZX-HY2.0-4PLT',addIntoBom:true});const pins=await eda.pcb_PrimitiveComponent.getAllPinsByPrimitiveId(c.getState_PrimitiveId());if(pins.length!==6)throw Error('Pin count');for(const p of pins){if(!await eda.pcb_PrimitivePad.modify(p,{net:z.nets[p.getState_PadNumber()]||''}))throw Error('Pin net');}for(const a of await eda.pcb_PrimitiveAttribute.getAll(c.getState_PrimitiveId()))await eda.pcb_PrimitiveAttribute.modify(a,{keyVisible:false,valueVisible:false});out.push({ref:z.ref,id:c.getState_PrimitiveId(),fp:c.getState_Footprint()});}return {out,saved:await eda.pcb_Document.save()};"
(P/'scripts/replace-hy20-pcb-v13.js').write_text(code,encoding='utf8')
rid={r['id'] for r in plan['routes'] if 'id' in r};vid={v['id'] for v in plan['vias'] if 'id' in v}
dr=[r['id'] for r in baseline['routes'] if r['id'] not in rid];dv=[v['id'] for v in baseline['vias'] if v['id'] not in vid]
code=guard+'const rs='+json.dumps(dr)+';const vs='+json.dumps(dv)+";for(const id of rs)if(!await eda.pcb_PrimitivePolyline.get(id))throw Error('Missing route '+id);for(const id of vs)if(!await eda.pcb_PrimitiveVia.get(id))throw Error('Missing via '+id);if(rs.length&&!await eda.pcb_PrimitivePolyline.delete(rs))throw Error('Delete routes');if(vs.length&&!await eda.pcb_PrimitiveVia.delete(vs))throw Error('Delete vias');return {removedRoutes:rs.length,removedVias:vs.length,saved:await eda.pcb_Document.save()};"
(P/'scripts/remove-hy20-old-copper-v13.js').write_text(code,encoding='utf8')
items=[{'kind':'via',**v} for v in plan['vias'] if 'id' not in v]+[{'kind':'route',**r} for r in plan['routes'] if 'id' not in r]
code=guard+'const items='+json.dumps(items)+";const EPCB_PrimitiveViaType={VIA:0};const out=[];for(const z of items){let p;if(z.kind==='via'){p=await eda.pcb_PrimitiveVia.create(z.net,z.x/.0254,z.y/.0254,z.hole/.0254,z.diameter/.0254,EPCB_PrimitiveViaType.VIA,null,{topSolderMask:-z.diameter/2/.0254,bottomSolderMask:-z.diameter/2/.0254},false);}else{const a=z.pointsMm;p=await eda.pcb_PrimitivePolyline.create(z.net,z.layer,eda.pcb_MathPolygon.createPolygon([...a[0].map(v=>v/.0254),'L',...a.slice(1).flatMap(q=>q.map(v=>v/.0254))]),z.widthMm/.0254,false);}if(!p)throw Error('Create copper');out.push(p.getState_PrimitiveId());}return {created:out.length,saved:await eda.pcb_Document.save()};"
(P/'scripts/apply-hy20-local-copper-v13.js').write_text(code,encoding='utf8')
print('PCB connectors 3; remove',len(dr),'traces',len(dv),'vias; add',len(items),'primitives; final vias',len(plan['vias']))
